using UnityEngine;
using HarborValeGreybox.Driving;
namespace HarborValeGreybox.Racing {
// Uses the same steering, powertrain, suspension and tires as the player. No velocity assignment/rubber banding.
public sealed partial class RoadPilot:MonoBehaviour {
 static int nextPriority;public int Priority{get;private set;}void Awake(){Priority=++nextPriority;}public FinchVehicle Car;public Vector3[] Path;public int Index;public float CruiseKph=36;public bool Held;public bool IsRival;public float Lane=1.75f;public int Recoveries{get;private set;}public float DistanceMoved{get;private set;}Vector3 previous;float stuck,impactAge=100,recoveryClock,flippedClock;int recoveryAttempts;public bool Recovering=>impactAge<22;public bool NeedsAssistedReset=>flippedClock>5||recoveryAttempts>=3&&recoveryClock>2;readonly RaycastHit[] hits=new RaycastHit[20];
 public Vector3 Point(int i){return LanePoint(i,Lane+laneShift);}Vector3 LanePoint(int i,float lane){i=(i%Path.Length+Path.Length)%Path.Length;var tangent=(Path[(i+1)%Path.Length]-Path[(i+Path.Length-1)%Path.Length]);tangent.y=0;tangent.Normalize();return Path[i]+new Vector3(tangent.z,0,-tangent.x)*lane;}
 public void Place(int i){Index=i%Path.Length;Car.ResetAt(Point(Index)+Vector3.up*.35f,Quaternion.LookRotation(Point(Index+2)-Point(Index)));ResetRaceLine();previous=Car.transform.position;stuck=0;impactAge=100;recoveryClock=flippedClock=0;recoveryAttempts=0;}
 public void RecoverAt(TrialGate gate){float best=float.MaxValue;for(int i=0;i<Path.Length;i++){float d=(Path[i]-gate.Position).sqrMagnitude;if(d<best){best=d;Index=i;}}Recoveries++;Car.ResetAt(gate.Position-gate.Forward*5+Vector3.Cross(Vector3.up,gate.Forward)*Lane+Vector3.up*.35f,Quaternion.LookRotation(gate.Forward));ResetRaceLine();previous=Car.transform.position;stuck=0;impactAge=100;recoveryClock=flippedClock=0;recoveryAttempts=0;}
 void OnCollisionEnter(Collision collision){if(collision.relativeVelocity.magnitude>2.5f||collision.impulse.magnitude>1000)NotifyImpact();}
 public void NotifyImpact(){if(Path==null||Path.Length<3)return;impactAge=0;recoveryClock=0;recoveryAttempts=0;flippedClock=0;float best=225;int nearest=Index;for(int n=-40;n<=40;n++){int i=(Index+n+Path.Length)%Path.Length;float d=(Point(i)-transform.position).sqrMagnitude;if(d<best){best=d;nearest=i;}}Index=nearest;}
 void Start(){previous=transform.position;}
 void FixedUpdate(){Drive(Time.fixedDeltaTime);}
 public void Drive(float dt){if(Car==null||Path==null||Path.Length<4)return;Car.externalInput=true;Car.commandedHandbrake=false;Car.commandedServiceBrake=Held?1:0;Car.commandedPedal=0;if(Held)return;impactAge+=dt;bool tipped=Vector3.Dot(Car.transform.up,Vector3.up)<.4f;if(tipped&&Car.SpeedKph<8){flippedClock+=dt;var upright=Vector3.Cross(Car.transform.up,Vector3.up);if(upright.sqrMagnitude<.01f)upright=Car.transform.forward;Car.Body.AddTorque(upright*Car.Body.mass*4,ForceMode.Force);Car.Body.AddForce(Vector3.up*Car.Body.mass*2,ForceMode.Force);}else flippedClock=0;var pos=Car.transform.position;DistanceMoved+=Vector3.Distance(pos,previous);previous=pos;
  for(int tries=0;tries<20;tries++){Vector3 next=Point(Index+1)-pos;next.y=0;if(next.magnitude<4||Vector3.Dot(Point(Index)-pos,Point(Index+1)-Point(Index))<0)Index=(Index+1)%Path.Length;else break;}
  UpdateRaceLine(dt);
  float look=Mathf.Clamp(4+Car.SpeedKph*.14f,4,14),distance=0;int goal=Index;for(int n=0;n<30&&distance<look;n++){distance+=Vector3.Distance(Point(goal),Point(goal+1));goal=(goal+1)%Path.Length;}
  Vector3 local=Car.transform.InverseTransformPoint(Point(goal));float angle=Mathf.Atan2(local.x,local.z);float steeringAngle=Mathf.Atan2(2*Car.wheelBase*Mathf.Sin(angle),Mathf.Max(3,local.magnitude))*Mathf.Rad2Deg;Car.commandedSteer=Mathf.Clamp(steeringAngle/Mathf.Lerp(Car.lowSpeedSteer,Car.highSpeedSteer,Mathf.Clamp01(Car.SpeedKph/130)), -1,1);
  float target=CornerSpeed();if(local.z<0)target=10;target=FollowTraffic(target);TargetKph=target;
  // Cars approaching crossing paths yield to the closer car; deterministic tie-break prevents mutual priority.
  foreach(var other in TrafficWorld.Agents){if(other==null||other==this||other.Car==null||ClosedCourse&&other.ClosedCourse)continue;var relative=other.transform.position-pos;if(relative.sqrMagnitude>18*18||Vector3.Dot(Car.transform.forward,relative)<0)continue;if(Mathf.Abs(Vector3.Dot(Car.transform.forward,other.transform.forward))>.7f)continue;Vector3 mine=pos+Car.transform.forward*8,theirs=other.transform.position+other.transform.forward*8;if(Vector3.Distance(mine,theirs)<10&&(other.Car.SpeedKph>2||other.Priority<Priority))target=0;}
  TargetKph=target;if(Car.SpeedKph>target+1.5f){Car.commandedServiceBrake=Mathf.Clamp01((Car.SpeedKph-target)/10);Car.commandedPedal=0;}else{Car.commandedServiceBrake=0;Car.commandedPedal=target<1?0:Mathf.Clamp((target-Car.SpeedKph)/(IsRival?7:14),0,IsRival?1:.65f);}
  if(Recovering&&Car.SpeedKph<5){recoveryClock+=dt;Vector3 toLane=Point(Index+2)-Car.transform.position;float heading=Vector3.SignedAngle(Car.transform.forward,toLane,Vector3.up);if(recoveryClock>1&&recoveryClock<3.1f){int rearHits=Physics.SphereCastNonAlloc(Car.transform.position-Car.transform.forward*2.6f+Vector3.up*.7f,.6f,-Car.transform.forward,hits,3,~((1<<28)|(1<<29)|(1<<31)),QueryTriggerInteraction.Ignore);bool clear=true;for(int h=0;h<rearHits;h++)if(!hits[h].collider.transform.IsChildOf(Car.transform)&&hits[h].normal.y<.7f)clear=false;if(clear){Car.commandedServiceBrake=0;Car.commandedPedal=-.32f;Car.commandedSteer=-Mathf.Sign(heading)*.75f;}else Car.commandedServiceBrake=1;}else if(recoveryClock>=3.1f&&recoveryClock<3.6f){Car.commandedPedal=0;Car.commandedServiceBrake=1;}else if(recoveryClock>=3.6f){Car.commandedPedal=.45f;Car.commandedServiceBrake=0;Car.commandedSteer=Mathf.Clamp(heading/30,-1,1);}if(recoveryClock>5){recoveryClock=0;recoveryAttempts++;}}else if(Car.SpeedKph>8)recoveryClock=0;
  if(Car.SpeedKph<2&&target>8)stuck+=dt;else stuck=0;if(stuck>12&&!IsRival&&TrafficWorld.CanReposition(Car.transform.position)){Recoveries++;Place(Index);}
 }
}
}
